test('renderInvoiceText shows paid amount when present', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(r1.ok, true);
  const r2 = issueInvoice(r1.value, []);
  assert.equal(r2.ok, true);
  const invoice = { ...r2.value, payments: [{ amount: 50000, date: '2026-10-01' }] };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(lines.some(l => l.startsWith('Paid:')));
