test('renderInvoiceText does not show paid when no payments', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);
  assert.ok(!text.includes('Paid:'));
});

test('renderInvoiceText with discounts, voucher, due date and paid', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 5 }],
  });
  assert.equal(r1.ok, true);
  const r2 = issueInvoice(r1.value, []);
  assert.equal(r2.ok, true);
  const invoice = {
    ...r2.value,
    voucher: { code: 'TEST', amount: 5000 },
    payments: [{ amount: 30000, date: '2026-10-01' }],
