  const text = renderInvoiceText(r.value);
  assert.ok(text.startsWith('DRAFT\n'));
});

test('renderInvoiceText displays invoice number when issued', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r1.ok, true);
  const r2 = issueInvoice(r1.value, []);
  assert.equal(r2.ok, true);
  const text = renderInvoiceText(r2.value);
  assert.ok(text.startsWith('INV-2026-0001\n'));
});

test('renderInvoiceText includes customer name', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  assert.equal(lines[1], 'Kite & Co');
});

test('renderInvoiceText displays one line per invoice line', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // number, name, line1, discount1, line2, VAT, total
  assert.equal(lines.length, 7);
  assert.equal(lines[2], '10 x Design work (hour) @ €85.00 €850.00');
  assert.equal(lines[3], '  Discount: -€21.25');
  assert.equal(lines[4], '5 x Development (hour) @ €95.00 €475.00');
});

test('renderInvoiceText formats amounts in euros', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'ICON-SET', qty: 100 }],
  });
  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // ICON-SET is 980 cents, 100 * 980 = 98000 cents = €980.00
  assert.equal(lines[2], '100 x Icon set (24 icons) @ €9.80 €980.00');
});

test('renderInvoiceText shows correct total', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // 10 * 8500 = 85000, discount 2125, VAT on 82875 = 17403.75 ≈ 17404
  // 5 * 9500 = 47500, no discount, VAT on 47500 = 9975
  // Total: 85000 + 47500 - 2125 + 17404 + 9975 = 157754 cents = €1,577.54
  assert.equal(lines[5], 'VAT: €274.79');
  assert.equal(lines[6], 'Total: €1,577.54');
});

test('renderInvoiceText with single line invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1000 }],
  });
  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // number, name, 1 line, discount, VAT, total
  assert.equal(lines.length, 6);
  assert.ok(lines[2].includes('Sticker sheet'));
  // Subtotal: 1000 * 50 = 50000 cents
  // Bulk discount: 50000 * 2.5% = 1250 cents
  // VAT: round((50000 - 1250) * 21/100) = round(48750 * 21/100) = 10237.5 ≈ 10238 cents = €102.38
  // Total: 50000 - 1250 + 10238 = 58988 cents = €589.88
  assert.equal(lines[3], '  Discount: -€12.50');
  assert.equal(lines[4], 'VAT: €102.38');
  assert.equal(lines[5], 'Total: €589.88');
});

